def solve(tokens):
    """Evaluate Reverse Polish Notation with truncating division toward zero.
    Handles large integers safely without floating point.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # Use integer arithmetic to avoid float precision issues
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                sign = -1 if (a < 0) ^ (b < 0) else 1
                stack.append(sign * (abs(a) // abs(b)))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

