    Cells with value 1 that are adjacent up/down/left/right form an island.
    Missing entries in shorter rows are treated as 0.
    """
    if not grid:
        return 0
    m = len(grid)
    # maximum number of columns in any row
    max_n = max((len(row) for row in grid), default=0)
    visited = set()
    def get(val_grid, i, j):
        # return cell value or 0 if out of bounds
        if 0 <= i < m and 0 <= j < len(val_grid[i]):
            return val_grid[i][j]
        return 0
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if nx < 0 or nx >= m:
                    continue
                if ny < 0 or ny >= len(grid[nx]):
                    continue
                if (nx, ny) not in visited and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    islands = 0
    for i in range(m):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                islands += 1
    return islands

