import bisect
def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    if not nums:
        return 0
    tails = []  # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # find insertion point (first >= x) for strict increase we need >
        i = bisect.bisect_left(tails, x)
        # for strictly increasing, we should replace at position of first >= x
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

